/* DAYMARK clarity pass: a direct goal, a few chosen actions, the full catalog on demand. */
VIEW_NAMES.supports='Мої кроки';
if(state.demo&&state.goals[0]?.title==='Сильніша версія себе'){state.goals[0].title='Підтримувати форму';persist();}
const clarityToastBase=toast;
toast=function(message,...args){return clarityToastBase(message==='Твої опори тепер під твій ритм. Календар збережено.'?'Мої кроки збережено. Календар на місці.':message,...args);};
const clarityReadoutBase=supportReadout;
supportReadout=function(x){if(!x.done)return clarityReadoutBase(x);const unit=n=>{if(x.unit==='записів')return Number(n)===1?'запис':Number(n)%10>=2&&Number(n)%10<=4&&(Number(n)%100<12||Number(n)%100>14)?'записи':'записів';return x.unit;};return 'Зроблено: '+num(x.value,1)+' '+unit(x.value)+' · план: '+num(x.target,1)+' '+unit(x.target);};

const previousClarityHome=homeApp;
homeApp=function(){return previousClarityHome().replace('<b>Мої опори</b><small>Мій набір під мою ціль</small>','<b>Мої кроки</b><small>Що зробити сьогодні</small>').replace('<span>🎯</span><span><b>Мої кроки','<span>🎯</span><span><b>Мої кроки');};
const previousClaritySpaces=spacesModal;
spacesModal=function(){previousClaritySpaces();const body=document.getElementById('modalBody');if(body)body.innerHTML=body.innerHTML.replaceAll('Мої опори','Мої кроки').replace('Мій набір','Мої дії');};

smartHabitPanel=function(){const g=goal(),s=supportsToday(g);return '<section class="supports-home-v3 clarity-home"><div class="supports-home-head"><div><span>ПІД ЦІЛЬ: '+esc(g.title)+'</span><h2>Мої кроки</h2><p>Ось дії, які ти обрав для свого дня.</p></div><button data-view="supports" aria-label="Відкрити мої кроки"><b>'+s.done.length+' із '+s.planned.length+'</b><small>зроблено ↗</small></button></div><div class="support-tiles">'+supportRows(g,true)+'</div><button class="support-customize" data-view="supports">Подивитися всі мої кроки <b>↗</b></button></section>';};

supportsView=function(){const g=goal(),s=supportsToday(g),t=GOAL_TEMPLATES[g.kind]||GOAL_TEMPLATES.custom,photo=({lose:'training-legs-v2.webp',gain:'food-day-v2.webp',muscle:'training-gear-v2.webp',sleep:'rest-evening-v2.webp',walking:'walk-park-v2.webp'}[g.kind]||'walk-park-v2.webp');return pageTop('Мої кроки','СЬОГОДНІ / '+fdate(selectedDate),dateControl())+'<section class="clarity-goal"><img src="assets/'+photo+'" alt="" loading="lazy"><div><span>МОЯ ЦІЛЬ</span><h2>'+esc(g.title)+'</h2><p>'+s.done.length+' із '+s.planned.length+' запланованих дій зроблено сьогодні</p><button data-view="goals">Переглянути мою ціль ↗</button></div><strong>'+s.done.length+'<small>/'+s.planned.length+'</small></strong></section><section class="clarity-actions"><div class="clarity-actions-head"><div><span>МІЙ ПЛАН НА СЬОГОДНІ</span><h2>Що мені зробити?</h2><p>Натисни на дію: внеси її тут або у відповідному щоденнику.</p></div></div><div class="support-tiles supports-tiles-full">'+supportRows(g)+'</div><button class="clarity-edit" data-action="supports-settings">Змінити ці дії <b>↗</b></button></section>'+(s.planned.length&&s.done.length===s.planned.length?'<button class="support-victory" data-action="quick-mark">Усі кроки є — закреслити день у календарі ↗</button>':'')+'<details class="clarity-week"><summary>Мій прогрес за останні 7 днів <b>↓</b></summary><div class="supports-week-v3">'+supportWeek(g)+'</div><p>Виконані дії за кожен день. Позначки календаря зберігаються окремо.</p></details><div class="clarity-minimum"><strong>На випадок складного дня</strong><p>'+esc(g.minimum)+'</p><button data-action="minimum">Відзначити свій мінімум ↗</button></div>'+(t.nutrition?'<button class="support-plan-link" data-action="plan">🍽 <span><b>Мій план харчування</b><small>Переглянути орієнтири калорій і БЖВ</small></span> ↗</button>':'');};

function clarityEditor(id,g){const d=SUPPORT_DEFINITIONS[id],x=supportRule(g,id);return '<div class="clarity-editor" data-id="'+id+'" data-group="'+d.group+'" data-search="'+esc((d.name+' '+d.sub).toLowerCase())+'">'+supportVisual(id,true)+'<label><input type="checkbox" name="support" value="'+id+'" '+(g.habits.includes(id)?'checked':'')+'><span><b>'+d.name+'</b><small>'+d.sub+'</small></span></label><details><summary>Налаштувати крок <span>↓</span></summary><div class="form-pair"><label class="form-label">Скільки, '+d.unit+'<input type="number" name="target_'+id+'" min="1" max="100000" step="any" value="'+x.target+'"></label><label class="form-label">Коли?<select name="schedule_'+id+'">'+[['daily','Щодня'],['weekdays','Пн–Пт'],['three','Пн, Ср, Пт'],['weekends','Сб–Нд']].map(([k,n])=>'<option value="'+k+'" '+(supportScheduleName(x.days)===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div><label class="form-label">Моя назва<input name="label_'+id+'" maxlength="80" value="'+esc(x.label)+'"></label>'+(id==='protein'?'<label class="recipe-checkbox"><input name="follow_protein" type="checkbox" '+(x.followPlan?'checked':'')+'>Орієнтир білка з мого плану</label>':'')+(d.auto?'<label class="recipe-checkbox"><input type="checkbox" name="auto_'+id+'" '+(x.automatic?'checked':'')+'>Брати записи зі щоденника автоматично</label>':'')+'</details></div>';}
const clarityEditorBase=clarityEditor;
clarityEditor=function(id,g){const synonyms={walk:'прогулянка ходити ходьба',outside:'прогулянка ходити вулиця',move:'прогулянка спорт тренування',food:'їжа харчування',strength:'тренування спорт зал',sleep:'сон спати',create:'блог відео контент',custom:'власна дія крок'};return clarityEditorBase(id,g).replace('data-search="','data-search="'+(synonyms[id]||'')+' ');};
supportsSettings=function(reset=false){const g=goal(),t=GOAL_TEMPLATES[g.kind]||GOAL_TEMPLATES.custom;if(!supportsDraft||reset)supportsDraft={ids:[...(reset?t.habits:g.habits)],rules:reset?{}:structuredClone(g.supportRules||{})};const selected=supportsDraft.ids.filter(id=>SUPPORT_DEFINITIONS[id]),other=Object.keys(SUPPORT_DEFINITIONS).filter(id=>!selected.includes(id));const groups=Object.entries(SUPPORT_GROUPS).map(([key,label])=>'<details class="clarity-group" data-group="'+key+'"><summary>'+({food:'🍽',move:'🏃',rest:'🌙',focus:'🎯',life:'🌿'}[key])+' <b>'+label+'</b><small>'+other.filter(id=>SUPPORT_DEFINITIONS[id].group===key).length+' варіантів</small></summary><div class="clarity-group-body">'+other.filter(id=>SUPPORT_DEFINITIONS[id].group===key).map(id=>clarityEditor(id,{...g,supportRules:supportsDraft.rules,habits:selected})).join('')+'</div></details>').join('');openModal('МОЇ КРОКИ / НАЛАШТУВАННЯ','<div class="clarity-config-head"><span>МОЯ ЦІЛЬ</span><h2>'+esc(g.title)+'</h2><p>Для початку достатньо кількох дій. Залиш ці або обери свої.</p></div><form id="supportsForm"><div class="clarity-selected-head"><h3>Зараз у моєму плані</h3><span id="claritySelectedCount">'+selected.length+' дії</span></div><div id="claritySelected">'+selected.map(id=>clarityEditor(id,{...g,supportRules:supportsDraft.rules})).join('')+'</div><details class="clarity-catalog" id="clarityCatalog"><summary>＋ Додати іншу дію <span>42 варіанти за темами ↓</span></summary><label class="clarity-search">Пошук дії<input type="search" id="claritySupportSearch" placeholder="Наприклад: сон, прогулянка, читання…"></label>'+groups+'</details><label class="form-label clarity-minimum-input">Мій мінімум у складний день<input name="minimum" maxlength="180" value="'+esc(g.minimum)+'" required></label><p class="form-error" id="supportsError" role="alert"></p><button class="btn blue full">Зберегти мої кроки</button><button class="text-btn full" type="button" data-action="supports-reset">Повернути запропоновані кроки для цієї цілі</button></form>');const form=document.getElementById('supportsForm');if(!form)return;const update=()=>{const checked=[...form.querySelectorAll('input[name="support"]:checked')].length;document.getElementById('claritySelectedCount').textContent=checked+' дії';form.querySelectorAll('.clarity-group').forEach(group=>{const count=group.querySelectorAll('.clarity-editor').length;group.querySelector('summary small').textContent=count+' варіантів';});};form.addEventListener('change',e=>{if(e.target.name!=='support')return;const row=e.target.closest('.clarity-editor');if(e.target.checked)document.getElementById('claritySelected').append(row);else form.querySelector('.clarity-group[data-group="'+row.dataset.group+'"] .clarity-group-body').append(row);update();});const search=document.getElementById('claritySupportSearch');search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();form.querySelectorAll('.clarity-group').forEach(group=>{let hits=0;group.querySelectorAll('.clarity-editor').forEach(row=>{const show=!q||row.dataset.search.includes(q);row.hidden=!show;if(show)hits++;});group.hidden=!!q&&!hits;if(q&&hits)group.open=true;});});};

const clarityOnboard=onboardSmartView;
onboardSmartView=function(){clarityOnboard();const form=document.getElementById('onboardForm');if(!form)return;const title=form.querySelector('.modal-title'),sub=form.querySelector('.modal-sub');if(onboard.step===0){title.textContent='Яка твоя ціль?';sub.textContent='Обери те, чого хочеш досягти. Назву й дії зможеш змінити.';}if(onboard.step===1){title.textContent='Коли починаєш?';sub.textContent='Постав свою дату. Це орієнтир для календаря, а не вимога ідеального результату.';}if(onboard.step!==2)return;title.textContent='З чого почнеш?';sub.textContent='Під ціль «'+(GOAL_TEMPLATES[onboard.kind]||GOAL_TEMPLATES.custom).name+'» пропонуємо кілька дій. Залиш їх або зміни.';const groups=[...form.querySelectorAll('.supports-group')];if(!groups.length)return;const selected=document.createElement('div');selected.className='onboard-selected';selected.innerHTML='<strong>Мої стартові дії</strong><small>Цього достатньо для початку</small>';sub.after(selected);const more=document.createElement('details');more.className='onboard-more';more.innerHTML='<summary>＋ Показати інші дії <span>за бажанням ↓</span></summary>';selected.after(more);groups.forEach(group=>{group.querySelectorAll('.onboard-support').forEach(row=>{if(row.querySelector('input[name="habit"]').checked)selected.append(row);});group.open=false;more.append(group);});form.addEventListener('change',e=>{if(e.target.name!=='habit')return;const row=e.target.closest('.onboard-support');if(e.target.checked)selected.append(row);else groups.find(group=>group.querySelector('summary').textContent===SUPPORT_GROUPS[SUPPORT_DEFINITIONS[e.target.value].group])?.append(row);});};
const claritySettingsBase=supportsSettings;
supportsSettings=function(...args){claritySettingsBase(...args);const caption=document.querySelector('#clarityCatalog>summary span');if(caption)caption.textContent='Їжа, рух, сон та інше ↓';};
const claritySettingsCounts=supportsSettings;
supportsSettings=function(...args){claritySettingsCounts(...args);const form=document.getElementById('supportsForm'),count=document.getElementById('claritySelectedCount');if(!form||!count)return;const refresh=()=>{const n=form.querySelectorAll('input[name="support"]:checked').length;count.textContent=n+' '+(n%10===1&&n%100!==11?'дія':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'дії':'дій');};refresh();form.addEventListener('change',e=>{if(e.target.name==='support')refresh();});};
const clarityOnboardBase=onboardSmartView;
onboardSmartView=function(...args){clarityOnboardBase(...args);if(onboard.step!==2)return;const form=document.getElementById('onboardForm');if(!form)return;const walker=document.createTreeWalker(form,NodeFilter.SHOW_TEXT);while(walker.nextNode()){if(walker.currentNode.textContent.includes('Опори, розклад і орієнтири'))walker.currentNode.textContent=walker.currentNode.textContent.replace('Опори, розклад і орієнтири','Дії, розклад і орієнтири');}};
